import type { Mock } from "vitest";
import type { H3Config, H3Event, NodeHandler, HTTPError } from "../src/index.ts";
import { tracingPlugin } from "../src/tracing.ts";
import { Server as NodeServer } from "node:http";
import { getRandomPort } from "get-port-please";
import { beforeEach, afterEach, vi, it, describe, expect, beforeAll, afterAll } from "vitest";
import { H3 } from "../src/index.ts";
import { toNodeHandler } from "../src/_entries/node.ts";

// Matrix
export function describeMatrix(
  title: string,
  fn: (ctx: TestContext, testUtils: TestUtils) => void | Promise<void>,
  opts?: TestOptions,
): void {
  const run = (ctx: TestContext) => {
    const utils: TestUtils = {
      expect,
      describe,
      it: Object.assign(interceptFnWithSuffix(it, ctx.target), {
        only: interceptFnWithSuffix(it.only, ctx.target),
        todo: interceptFnWithSuffix(it.todo, ctx.target),
        skip: interceptFnWithSuffix(it.skip, ctx.target),
        skipIf: (condition: boolean) => (condition ? utils.it.skip : utils.it),
        runIf: (condition: boolean) => (condition ? utils.it : utils.it.skip),
      }),
    };
    fn(ctx, utils);
  };
  describe(title, () => {
    describe("web", () => {
      run(setupWebTest(opts));
    });
    describe("node", () => {
      run(setupNodeTest(opts));
    });
  });
}

// Web
function setupWebTest(opts: TestOptions = {}): TestContext {
  const ctx = setupBaseTest("web", opts);
  beforeEach(() => {
    ctx.fetch = (input, init) => {
      const headers = new Headers(init?.headers);
      if (input.startsWith("/") && !headers.has("host") && !headers.has("x-forwarded-host")) {
        headers.set("Host", "localhost");
      }
      return Promise.resolve(
        ctx.app.request(input, {
          ...init,
          headers,
        }),
      );
    };
  });
  return ctx;
}

// Node.js
// Allowed characters: horizontal tabs, spaces or visible ascii characters: https://www.rfc-editor.org/rfc/rfc7230#section-3.1.2
// eslint-disable-next-line no-control-regex
const DISALLOWED_STATUS_CHARS = /[^\u0009\u0020-\u007E]/g;

/**
 * Make sure the status message is safe to use in a response.
 *
 * Allowed characters: horizontal tabs, spaces or visible ascii characters: https://www.rfc-editor.org/rfc/rfc7230#section-3.1.2
 */
export function sanitizeStatusMessage(statusMessage = ""): string {
  return statusMessage.replace(DISALLOWED_STATUS_CHARS, "");
}

/**
 * Make sure the status code is a valid HTTP status code.
 */
export function sanitizeStatusCode(statusCode?: string | number, defaultStatusCode = 200): number {
  if (!statusCode) {
    return defaultStatusCode;
  }
  if (typeof statusCode === "string") {
    statusCode = +statusCode;
  }
  // `Number.isInteger` rejects everything a bare range check would let through: `NaN` (from
  // `+statusCode` on a non-numeric string), floats, and non-numeric values such as objects or
  // arrays, whose comparisons are all `false`. Without it an invalid code leaks through and
  // breaks `Response`.
  if (!Number.isInteger(statusCode) || statusCode < 100 || statusCode > 599) {
    return defaultStatusCode;
  }
  return statusCode;
}

